static void printHelp(PrintWriter out) {
    out.println("Usage:");
    out.println("        vark [-f FILE] [options] [targets...]");
    out.println();
    out.println("Options:");

    IArgKeyList keys = Launch.factory().createArgKeyList();
    for (IArgKey key : AardvarkOptions.getArgKeys()) {
      keys.register(key);
    }
    keys.printHelp(out);
  }
